INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0020-000000000000', '정렬 알고리즘 중 평균적으로 가장 빠른 것은 어느 것인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000001', '버블 정렬(Bubble Sort)은 어떻게 동작하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000002', '퀵정렬이 최악의 경우(O(n^2)) 발생하는 입력은 어떤 경우인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000003', '동시에 여러 정렬 알고리즘을 비교해본다면 어떤 기준이 중요할까요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000004', '백트래킹(Backtracking)은 어떤 유형의 문제 해결 기법인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000005', '분기 한정 기법(Branch and Bound)에 대해 설명해 주세요.', 'HARD', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000006', '다이나믹 프로그래밍의 예로 피보나치 수열을 DP로 해결하는 방법은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000007', '메모이제이션(Memoization)은 무엇이며 DP에서 어떻게 활용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000008', '탐욕 알고리즘(Greedy)은 무엇이며 한 가지 예를 들어보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000009', '거꾸로 (뒤집어서) 생각하는 분할 정복(Divide and Conquer) 기법은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000a', '해싱(Hashing)이란 무엇이며, 충돌 해결 방법에는 무엇이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000b', '해시맵(Hash Map)과 트리맵(Tree Map)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000c', '우선순위 큐(Priority Queue)는 내부적으로 어떤 자료구조로 구현할 수 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000d', '그래프 탐색에서 Dijkstra 알고리즘은 어떤 문제를 풀기 위한 것이죠?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000e', '최단 경로 문제를 해결하는 알고리즘에는 어떤 것들이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-00000000000f', 'NP-완전 문제란 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000010', 'NP-완전과 NP-하드의 개념을 설명해 보세요.', 'HARD', 'b0000000-0000-0000-0000-000000000020'),
('b0000000-0000-0000-0020-000000000011', '결정 문제를 다루는 P vs NP 문제에 대해 들어본 적이 있나요?', 'HARD', 'b0000000-0000-0000-0000-000000000020');